import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.BTg7EidG.js";const u=JSON.parse('{"title":"Skills & Research","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills.md","filePath":"guide/skills.md"}'),i={name:"guide/skills.md"};function h(n,e,d,o,l,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="skills-research" tabindex="-1">Skills &amp; Research <a class="header-anchor" href="#skills-research" aria-label="Permalink to &quot;Skills &amp; Research&quot;">​</a></h1><h2 id="where-each-art-is-taught" tabindex="-1">Where each art is taught <a class="header-anchor" href="#where-each-art-is-taught" aria-label="Permalink to &quot;Where each art is taught&quot;">​</a></h2><p>The <strong>Town Hall</strong> teaches one art per class per tier — the old three. Everything else is taught where the trade actually lives, which is a reason to raise those structures beyond drilling in them:</p><table tabindex="0"><thead><tr><th>Building</th><th>What it teaches</th></tr></thead><tbody><tr><td><strong>Barracks</strong></td><td>Blinding Dust, Bulwark</td></tr><tr><td><strong>Laboratory</strong></td><td>Quickening Balm, Vitriol Flask, Quicken</td></tr><tr><td><strong>Shadow Guild</strong></td><td>Shadow Step, Assassinate, Poison Blade</td></tr><tr><td><strong>Bestiary</strong></td><td>Beast Bond, Wild Heart, Ensnare</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Nothing is innate</p><p>Your Lord begins with steel and a title, not a technique. <strong>Every</strong> skill is studied at a Town Hall — including your own class&#39;s art, which is simply the cheapest project on the list and the one to start with.</p></div><p>Every hero carries up to <strong>three skills</strong>. The first is the innate art of their class, locked in from the day they take command; the rest are earned in the study and assigned from the unit sheet.</p><h2 id="how-research-works" tabindex="-1">How research works <a class="header-anchor" href="#how-research-works" aria-label="Permalink to &quot;How research works&quot;">​</a></h2><p>Research happens at the <strong>Town Hall</strong> of any city you own; the hall&#39;s level is the city&#39;s level, and it gates what can be studied:</p><table tabindex="0"><thead><tr><th>Hall level</th><th>Opens</th><th>Cost</th><th>Time</th></tr></thead><tbody><tr><td>1</td><td>The class skills (innate, free)</td><td>—</td><td>—</td></tr><tr><td>2</td><td>The deeper studies (tier 2)</td><td>150🪙 10💎</td><td>5 days</td></tr><tr><td>3</td><td>The masterworks (tier 3)</td><td>200🪙 16💎</td><td>6 days</td></tr></tbody></table><p>One project sits on the bench at a time, guild-wide. Once a skill is mastered it belongs to the whole guild forever: <strong>any hero of the right class</strong> can assign it from their unit sheet, from that day on. A mastered skill can be unassigned and reassigned freely; only the innate class skill is fixed.</p><h2 id="the-warrior-s-line" tabindex="-1">The warrior&#39;s line <a class="header-anchor" href="#the-warrior-s-line" aria-label="Permalink to &quot;The warrior&#39;s line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>What it does</th></tr></thead><tbody><tr><td>📣 Rally</td><td>1 · innate</td><td>The whole party fights at +2 attack and +2 defense while this hero leads</td></tr><tr><td>🛡 Shield Wall</td><td>2</td><td>The party braces at +3 defense whenever it is the one attacked</td></tr><tr><td>📯 Warcry</td><td>3</td><td>The enemy line falters: every foe fights at −2 defense</td></tr></tbody></table><p>Warriors anchor a line. Rally is always on; Shield Wall turns a garrisoned warrior hero into a wall worth breaking armies on; Warcry is the siege-breaker, softening a deep garrison before the blades cross. Rally and Warcry together swing every exchange by four points.</p><h2 id="the-rogue-s-line" tabindex="-1">The rogue&#39;s line <a class="header-anchor" href="#the-rogue-s-line" aria-label="Permalink to &quot;The rogue&#39;s line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>What it does</th></tr></thead><tbody><tr><td>🌫 Ambush</td><td>1 · innate</td><td>A free opening volley whenever this party attacks, +15% to a fleeing Lord&#39;s escape, and ambushes are sprung more often</td></tr><tr><td>🪙 Plunder</td><td>2</td><td>Hoards turn up in 60% of taken holds instead of 40%, and dungeon chests run half again as rich</td></tr><tr><td>⚔ Overwhelm</td><td>3</td><td>The class counter (warrior beats rogue beats alchemist beats warrior) deals double damage instead of half again, for the whole party</td></tr></tbody></table><p>Rogues profit from initiative and greed. Ambush makes every attack begin a step ahead; Plunder pays for itself within a few raids, and it belongs on whichever hero storms the most holds; Overwhelm rewards building a party that counters what your enemy fields. Rogue heroes also sneak parties past dungeon floors, and flee down stairs mid-fight.</p><h2 id="the-alchemist-s-line" tabindex="-1">The alchemist&#39;s line <a class="header-anchor" href="#the-alchemist-s-line" aria-label="Permalink to &quot;The alchemist&#39;s line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>What it does</th></tr></thead><tbody><tr><td>⚗️ Transmute Blast</td><td>1 · innate</td><td>Opens battle by burning half the hero&#39;s Essence as damage that ignores armor (on the tactical field, a cast at range 3)</td></tr><tr><td>🩹 Field Mending</td><td>2</td><td>The whole party heals an extra 10% of max HP every day, even on the march</td></tr><tr><td>🌀 Quicksilver March</td><td>3</td><td>The hero&#39;s craft lightens every boot: the party marches +3 move points a day</td></tr></tbody></table><p>Alchemists win wars between the battles. Transmute Blast scales with Essence, so a leveled alchemist Lord opens with a thunderclap; Field Mending keeps a campaigning army whole without ever going home; and Quicksilver March makes one army fight like two by arriving first. Put March on the party that answers threats, and Mending on the one that never stops pushing.</p><h2 id="reading-the-research-screen" tabindex="-1">Reading the research screen <a class="header-anchor" href="#reading-the-research-screen" aria-label="Permalink to &quot;Reading the research screen&quot;">​</a></h2><p>Open any city&#39;s <strong>Research</strong> tab: each skill shows its class, tier, cost, and state. <em>Class skill</em> means innate; <em>mastered</em> means done and assignable; <em>on the bench</em> is the current project. A skill grayed with &quot;needs hall 2/3&quot; wants the city upgraded first, and upgrading any one city to level 3 opens the masterworks for the whole guild.</p>',21)])])}const m=t(i,[["render",h]]);export{u as __pageData,m as default};
